//=============================================================================
// ReXGlue Generated - generations Function Registration
//=============================================================================

#include "generations_init.h"
#include <rex/system/function_dispatcher.h>

#include <charconv>
#include <cstdlib>
#include <fstream>
#include <string>
#include <unordered_set>

namespace {

// Diagnostic-only registration filter. Normal launches do not set the
// environment variable and register every function exactly as generated.
class RegistrationFilter final : public rex::runtime::IModuleRegistrar {
 public:
  explicit RegistrationFilter(rex::runtime::IModuleRegistrar* registrar)
      : registrar_(registrar) {
    const char* path = std::getenv("REX_SKIP_REGISTRATION_TOML");
    if (!path || !*path) {
      return;
    }

    std::ifstream input(path);
    for (std::string line; std::getline(input, line);) {
      const size_t prefix = line.find("\"0x");
      if (prefix == std::string::npos || prefix + 11 > line.size()) {
        continue;
      }

      uint32_t address = 0;
      const char* begin = line.data() + prefix + 3;
      const char* end = begin + 8;
      auto result = std::from_chars(begin, end, address, 16);
      if (result.ec == std::errc{} && result.ptr == end) {
        skipped_addresses_.insert(address);
      }
    }
  }

  bool SetFunction(uint32_t guest_address, PPCFunc* func) override {
    if (skipped_addresses_.contains(guest_address)) {
      return true;
    }
    return registrar_->SetFunction(guest_address, func);
  }

 private:
  rex::runtime::IModuleRegistrar* registrar_;
  std::unordered_set<uint32_t> skipped_addresses_;
};

}  // namespace


